local _src = vim.fs.abspath(debug.getinfo(1).source:sub(2))
local _test_dir = vim.fs.dirname(_src)
package.path = _test_dir .. "/?.lua;" .. vim.fs.dirname(_test_dir) .. "/lua/?.lua;" .. package.path
local H = require "harness"
local core = require("zathura_cite.core")
local zc = dofile(vim.fs.dirname(vim.fs.dirname(_src)) .. "/plugin/zathura_cite.lua")
local vault = "/home/ls/knowledge_library"
local tmp = vim.fn.tempname() .. "_zce"
vim.fn.mkdir(tmp, "p")
local function w(name, content)
  local p = tmp .. "/" .. name
  local f = io.open(p, "w"); f:write(content); f:close(); return p
end

H.describe("match_citation_line edge", function()
  H.it("markdown link without .pdf -> nil", function()
    H.falsy(core.match_citation_line('[x](' .. vault .. '/note/evo.md) p.3: "q"', vault))
  end)
  H.it("wiki abs target", function()
    local m = core.match_citation_line('[[' .. vault .. '/literature/2017_msckf_notes.pdf]] p.4: "q"', vault)
    H.truthy(m)
    H.eq(m.file, vault .. '/literature/2017_msckf_notes.pdf')
    H.eq(m.page, 4)
  end)
  H.it("multi-digit page", function()
    local m = core.match_citation_line('[[literature/2017_msckf_notes|t]] p.12: "q"', vault)
    H.truthy(m); H.eq(m.page, 12)
  end)
  H.it("p.N before link still first match", function()
    local m = core.match_citation_line('see p.2 then [[literature/2017_msckf_notes|t]] p.9: "q"', vault)
    H.truthy(m); H.eq(m.page, 2)
  end)
  H.it("p.N without any link -> nil", function()
    H.falsy(core.match_citation_line('see p.2 in the paper', vault))
  end)
  H.it("line with only text -> nil", function()
    H.falsy(core.match_citation_line('just some text', vault))
  end)
end)

H.describe("install_zathurarc edge", function()
  H.it("replaces stale zath-cite map line (different script path)", function()
    local rc = w("rc_old", "set font x\nmap Y exec /old/path/zath-cite.sh\\ $PAGE\n")
    H.truthy(zc.install_zathurarc(rc, tmp .. "/new.sh"))
    local s2 = io.open(rc):read("*a")
    H.truthy(s2:find("set font x", 1, true), "unrelated line kept")
    H.falsy(s2:find("/old/path/zath-cite.sh", 1, true), "stale line removed")
    H.truthy(s2:find("map Y exec " .. tmp .. "/new.sh\\ $PAGE", 1, true))
    H.falsy(zc.install_zathurarc(rc, tmp .. "/new.sh"), "idempotent after replace")
  end)
  H.it("existing file without trailing newline", function()
    local rc = w("rc2", "set something")
    H.truthy(zc.install_zathurarc(rc, tmp .. "/s.sh"))
    local s = io.open(rc):read("*a")
    H.truthy(s:find("\nmap Y exec " .. tmp .. "/s.sh\\ $PAGE", 1, true), "newline inserted before new line")
    H.falsy(zc.install_zathurarc(rc, tmp .. "/s.sh"))
  end)
  H.it("existing unrelated line stays", function()
    local rc = w("rc3", "set font x\n")
    zc.install_zathurarc(rc, tmp .. "/s.sh")
    local s = io.open(rc):read("*a")
    H.truthy(s:find("set font x", 1, true))
  end)
end)

H.run()
if vim.v.exception == "" then vim.fn.delete(tmp, "rf") end
